blocks.code:
h1 {
  font-size: 36px;
}

p {
  color: #4b5563;
}

button {
  padding: 10px 16px;
}

.button {
  border: none;
  border-radius: 8px;
  padding: 10px 16px;
}

.primary {
  background: #2563eb;
  color: white;
}

.large {
  font-size: 18px;
  padding: 14px 24px;
}

h1,
h2,
h3 {
  color: #111827;
  font-family: Arial, sans-serif;
}

p {
  color: black;
}

.note {
  color: blue;
}

#special-note {
  color: red;
}

.dashboard {
  font-family: Arial, sans-serif;
}

.dashboard-header {
  padding: 24px;
  background: #0f172a;
  color: white;
}

#dashboard-title {
  margin: 0;
  font-size: 32px;
}

.dashboard-nav {
  padding: 12px 24px;
  background: #e2e8f0;
}

.dashboard-nav .nav-link {
  color: #334155;
  text-decoration: none;
  margin-right: 18px;
}

.dashboard-nav .nav-link.active {
  color: #2563eb;
  font-weight: 700;
}

.dashboard-content {
  padding: 24px;
}

.dashboard-card {
  background: white;
  padding: 20px;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  margin-bottom: 20px;
}

.dashboard-card h2 {
  margin-top: 0;
}

.dashboard-card p {
  color: #64748b;
}
